import { z } from 'zod';

/** UUID, as generated by Postgres `gen_random_uuid()`. */
export const Id = z.uuid();

/** ISO 8601 in UTC with a `Z` suffix, e.g. `2026-10-19T08:30:00.000Z`. */
export const Timestamp = z.iso.datetime();

/** Opaque pagination cursor returned as `nextCursor`. */
export const Cursor = z.string().min(1).max(200);

export const page = <T extends z.ZodType>(item: T) => z.object({ items: z.array(item), nextCursor: Cursor.nullable() });

/** Every error response: RFC 9457 problem details (`application/problem+json`). */
export const Problem = z.object({
  type: z.string(),
  title: z.string(),
  status: z.number().int(),
  detail: z.string().optional(),
  /** Field-level problems for 422 responses. `path` is dot-separated, e.g. `readings.0.humidityPct`. */
  errors: z.array(z.object({ path: z.string(), message: z.string() })).optional(),
});
export type Problem = z.infer<typeof Problem>;
